import{z as n,x as A,o as t,c as B,q as l,j as s,D as a,d as o,s as r,S as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"CUTLASS 的结构直觉","description":"","frontmatter":{"title":"CUTLASS 的结构直觉","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-cutlass-intuition.md","filePath":"cs/gpu-cutlass-intuition.md","lastUpdated":1791063341000}'),c={name:"cs/gpu-cutlass-intuition.md"};function m(p,e,u,d,C,S){const i=A("Mermaid");return t(),B("div",null,[e[2]||(e[2]=l('<h1 id="cutlass-的结构直觉" tabindex="-1">CUTLASS 的结构直觉 <a class="header-anchor" href="#cutlass-的结构直觉" aria-label="Permalink to &quot;CUTLASS 的结构直觉&quot;">​</a></h1><div class="epigraph"><p>CUTLASS 把 GEMM 拆成四层可换件——调度、流水、收尾、指令；分层的判据只有一条：换这一层时，别的层不用动。</p><footer>—— 据 NVIDIA CUTLASS 文档整理</footer></div><p><a href="/cs/gpu-tensorcore-programming">上一课</a>把 MMA 的三层抽象与喂料模板摆出；从指令到一个生产级 GEMM 还差两件事：tile 怎么调度、流水怎么叠。大模型栏的 <a href="/llm/cutlass">CUTLASS 层次</a>与 <a href="/llm/cutlass3-cute">cuTeDSL / CUTLASS 3</a>做过层次走读与 API 细读，<a href="/llm/thunderkittens">ThunderKittens</a> 给了另一套抽象的对照。本课写结构直觉：这套分层为什么成立、每层交换什么、改需求时该在哪层动手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生产级 GEMM 叠着几组相互正交的决策：tile 的二维排布（防 L2 抖动、均衡负载）、主循环的 stage 数与缓冲、warp 任务的划分、epilogue 的融合（激活、偏置、量化都挂在这）、以及跨代指令的选择。逐个手写是组合爆炸：五个维度各三档就是上百个内核。CUTLASS 的回答不是「更聪明的代码生成」，而是先回答一个结构问题：这些决策里哪些正交到可以独立替换？分层分错了的代价是可见的——把 epilogue 写死在主循环里的库，每加一种激活就要复制整个 GEMM。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四层从外到内，每层认领一组决策。device 层认调度：tile 到 block 的映射——线性序加 swizzle 换 L2 局部性；persistent 与 Stream-K 换负载均衡，把「一个 block 做一个 tile」改成「一个 block 吃完一批 tile」或「把残余的 k 段拆给闲下来的 block」（<a href="/llm/persistent-kernel">persistent kernel 课</a>给过前者的机制）。collective 层认主循环：global 到 smem 的多 stage 流水加 MMA，合同是 smem 容量除以 stage 数，<a href="/llm/sw-pipeline-buffer">软件流水课</a>的账在这里兑现；Hopper 的 warp 特化（生产者拷贝、消费者 MMA）是这一层在 sm90 上的形态。epilogue 层认写出：smem 到 global 的布局变换与逐元素融合，激活函数挂在这层的 visitor 上。atom 层认指令：copy atom 与 mma atom 是上一课三层抽象的封装，跨代换件——sm80 的 <code>cp.async</code> 加 <code>mma.sync</code> 换成 sm90 的 TMA 加 wgmma，collective 之上的代码不动。</p>',7)),(t(),s(E,null,{default:a(()=>[r(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22device%EF%BC%9Atile%20%E8%B0%83%E5%BA%A6%EF%BC%88swizzle%20%2F%20persistent%20%2F%20Stream-K%EF%BC%89%22%5D%20--%3E%20COL%5B%22collective%EF%BC%9A%E4%B8%BB%E5%BE%AA%E7%8E%AF%E6%B5%81%E6%B0%B4%EF%BC%88stage%20%E6%95%B0%20%2F%20warp%20%E7%89%B9%E5%8C%96%EF%BC%89%22%5D%0A%20%20COL%20--%3E%20ATOM%5B%22atom%EF%BC%9Acopy%20%E4%B8%8E%20mma%20%E6%8C%87%E4%BB%A4%E5%B0%81%E8%A3%85%EF%BC%8C%E8%B7%A8%E4%BB%A3%E6%8D%A2%E4%BB%B6%22%5D%0A%20%20COL%20--%3E%20EPI%5B%22epilogue%EF%BC%9A%E5%86%99%E5%87%BA%E4%B8%8E%E8%9E%8D%E5%90%88%EF%BC%88visitor%20%E6%8C%82%E6%BF%80%E6%B4%BB%EF%BC%89%22%5D%0A%20%20EPI%20--%3E%20G%5B%22global%20%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模板分层为什么可行：所有决策在编译期实例化，层与层只交换布局与坐标，不交换运行时对象——没有虚调用，分层不付间接税。层间语言是 CuTe 的 layout 代数：<code>shape : stride</code> 的张量加 compose、slice 两个操作，epilogue 拿到的不是裸指针而是「带布局的视图」，所以融合一个激活不需要知道主循环的 swizzle 细节。跨代复制配置不成立的原因也在这层结构里：atom 换代意味着布局合同变了（上一课的 8/4/4 变成 wgmma 的 smem 操作数），swizzle 模式与 stage 数的合法解集随之变——参数表是「某一代硬件 + 某一算法」的解，不是普适常数，<a href="/llm/cutlass">CUTLASS 层次课</a>的结论「架构是模板的一部分」说的就是这个。</p><p><span class="marginnote">数字实例：collective 层的 stage 合同是「smem 容量 ÷ stage 数 = 单个 stage 的字节数」。sm80 一块 smem 约 164 KB：tile 尺寸 A+B 各 128×32 的 fp16 时每 stage 约 16 KB，理论能开 8 stage；换成 128×64 就要砍半。改 tile 尺寸后必须重算 stage 数，否则编译期直接报 smem 溢出——这就是「换这层、别层要复核合同」的具体样子。</span></p><p><span class="marginnote">常见误区：初学者容易以为「分层=运行时多态=变慢」。CUTLASS 的分层全部在编译期展开：换 epilogue 的激活函数是换模板参数，生成的代码里连函数指针都没有，更没有虚表查找。慢的是「运行时再决定」，不是「代码组织上分层」。</span></p>',4)),(t(),s(E,null,{default:a(()=>[r(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E9%9C%80%E6%B1%82%EF%BC%9A%E6%8D%A2%E6%BF%80%E6%B4%BB%E5%87%BD%E6%95%B0%22%5D%20--%3E%20W%7B%22%E5%8A%A8%E5%93%AA%E4%B8%80%E5%B1%82%22%7D%0A%20%20W%20--%3E%7C%22%E6%8D%A2%20swizzle%20%E6%88%96%E8%B0%83%E5%BA%A6%22%7C%20D%5B%22%E5%8F%AA%E6%94%B9%20device%20%E5%B1%82%22%5D%0A%20%20W%20--%3E%7C%22%E6%8D%A2%20stage%20%E6%88%96%E6%B5%81%E6%B0%B4%22%7C%20C%5B%22%E5%8F%AA%E6%94%B9%20collective%20%E5%B1%82%22%5D%0A%20%20W%20--%3E%7C%22%E6%8D%A2%20GELU%20%E4%B8%BA%20SiLU%22%7C%20E%5B%22%E5%8F%AA%E6%94%B9%20epilogue%20visitor%22%5D%0A%20%20W%20--%3E%7C%22sm80%20%E6%8D%A2%20sm90%20%E6%8C%87%E4%BB%A4%22%7C%20A%5B%22%E5%8F%AA%E6%8D%A2%20atom%20%E4%B8%8A%E5%B1%82%E4%BB%A3%E7%A0%81%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>API 走读与实例代码归大模型栏那两课，本课只给「在哪层换什么」的地图。CUTLASS 不是唯一抽象：ThunderKittens 用更小的原语面换更陡的学习曲线，Triton 把 tile 层交给编译器（<a href="/llm/triton-attention-kernel">Triton 写注意力核</a>）；抽象的选择标准是你要改哪一层。autotuning 的方法（扫 stage 与 tile 的网格、记录配置）在 profiling 课之后另有归宿，本课不展开。也别把 CUTLASS 当默认答案：标准形状下 <a href="/llm/cublas-cudnn">cuBLAS</a> 先行，CUTLASS 的价值在可改与库外融合。</p><p><span class="marginnote">threadblock swizzle 的最小示例：把 tile 的线性序按每 8 列一组蛇形重排，相邻 block 同时算的 tile 在空间上聚簇，L2 命中率即可观上升——device 层一行的改动，主循环一行不动；能指出改动属于哪层，就是这套分层的用法。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分层判据是「换这层、别层不动」：调度在 device、流水在 collective、收尾在 epilogue、指令在 atom。</li><li>层间语言是布局与坐标（CuTe 的 layout 代数），不是指针与循环边界。</li><li>编译期实例化让分层不付间接税；运行时没有虚调用。</li><li>跨代复制参数表不成立：atom 换代即布局合同换代，合法解集随之变。</li><li>选抽象先问要改哪层：库兜底走 cuBLAS，改融合走 CUTLASS，改 tile 语义走 Triton 或更小的原语面。</li><li>出处：NVIDIA CUTLASS 与 CUTLASS 3.x / CuTe 文档。</li></ul>',5))])}const h=n(c,[["render",m]]);export{g as __pageData,h as default};
